     "instruction": "Completa le frasi con l'articolo partitivo corretto.",
     "body": "1. Fai ___ errori dovuti alla tua distrazione.\n2. Prendi ___ acqua per far bollire ___ patate per stasera.\n3. Stefano ha comprato ___ bellissime scarpe da ginnastica.\n4. Vorrei ___ francobolli per il Perù.\n5. Metti nella valigia ___ calze, ___ magliette, ___ mutande e un paio di pantaloni.\n6. Il telegiornale ha trasmesso ___ notizie terribili sulla guerra in Cecenia.\n7. Mia zia ha ___ sorelle non molto simpatiche.\n8. I vicini di casa di Giulia hanno ___ modi di fare insopportabili.",
     "answerBody": "1. Fai **degli** errori dovuti alla tua distrazione.\n2. Prendi **dell'** acqua per far bollire **delle** patate per stasera.\n3. Stefano ha comprato **delle** bellissime scarpe da ginnastica.\n4. Vorrei **dei** francobolli per il Perù.\n5. Metti nella valigia **delle** calze, **delle** magliette, **delle** mutande e un paio di pantaloni.\n6. Il telegiornale ha trasmesso **delle** notizie terribili sulla guerra in Cecenia.\n7. Mia zia ha **delle** sorelle non molto simpatiche.\n8. I vicini di casa di Giulia hanno **dei** modi di fare insopportabili.",
