     "num": "01",
     "instruction": "Sottolinea nel brano i nomi comuni e metti la lettera maiuscola ai nomi propri.",
     "body": "Il sindaco si mette alla guida dell'auto municipale per trasportare i concittadini non serviti dal trasporto pubblico. Sta succedendo a drezzo (como), comune di mille abitanti al confine con la svizzera. Per più di due mesi l'autobus non potrà transitare, perché un cantiere interrompe la strada. E dal momento che la spt, la società che gestisce la linea, non ha istituito un servizio navetta, è intervenuto il primo cittadino, lorenzo canepa, che ha messo disposizione la fiat uno del comune per trasportare gli utenti alla fermata più vicina, a due chilometri dal paese, mettendosi personalmente alla guida, quando è necessario.\n\n(da «L'Avvenire», 13 giugno 2001)",
     "answerBody": "Testo corretto (sottolineati = nomi comuni; maiuscole aggiunte ai nomi propri):\n> Il **sindaco** si mette alla **guida** dell'**auto** municipale per trasportare i **concittadini** non serviti dal **trasporto** pubblico. Sta succedendo a **Drezzo (Como)**, **comune** di mille **abitanti** al **confine** con la **Svizzera**. Per più di due **mesi** l'**autobus** non potrà transitare, perché un **cantiere** interrompe la **strada**. E dal momento che la **SPT**, la **Società** che gestisce la **linea**, non ha istituito un **servizio** navetta, è intervenuto il primo **cittadino**, **Lorenzo Canepa**, che ha messo a disposizione la **Fiat** Uno del **comune** per trasportare gli **utenti** alla **fermata** più vicina, a due **chilometri** dal **paese**, mettendosi personalmente alla **guida**, quando è necessario.\n- Nomi propri corretti: Drezzo, Como, Svizzera, SPT, Società, Lorenzo Canepa, Fiat\n- (da «L'Avvenire», 13 giugno 2001)",
