     "instruction": "Completa le frasi con il pronome personale complemento corretto.",
     "body": "1. Se vuoi parlare con Federico, telefona ___ subito, perché poi va via.\n2. La mamma compie gli anni. Regaliamo ___ un profumo.\n3. Se avete deciso di chiedere scusa a Fatima, parlate ___ ora.\n4. Se continuate a dir ___ un mucchio di bugie, come posso fidarmi di voi?\n5. Posso telefonar ___ verso le sette o dormite ancora?\n6. Dicendo ___ queste cose, lo hai fatto arrabbiare.",
