   "id": 17,
   "title": "Gli aggettivi e i pronomi possessivi",
   "file": "scheda17_gliaggettivieipronomipossessivi.md",
   "theory": "## Gli aggettivi e i pronomi possessivi\nI POSSESSIVI SERVONO PER INDICARE A CHI APPARTIENE UNA PERSONA O UNA COSA.\n\n### LA FORMA\n| Persona | Singolare | | Plurale | |\n|---|---|---|---|---|\n| | maschile | femminile | maschile | femminile |\n| 1a sing. (io) | mio | mia | miei | mie |\n| 2a sing. (tu) | tuo | tua | tuoi | tue |\n| 3a sing. (lui/lei) | suo | sua | suoi | sue |\n| 1a pl. (noi) | nostro | nostra | nostri | nostre |\n| 2a pl. (voi) | vostro | vostra | vostri | vostre |\n| 3a pl. (loro) | loro | loro | loro | loro |\n\nI possessivi possono essere:\n\n- aggettivi possessivi, quando accompagnano il nome\n\n    il mio orologio, la tua bicicletta, il suo ufficio, la nostra scuola, la vostra insegnante, il loro alloggio\n\n- pronomi possessivi, quando il nome non c'è, perché il pronome sta al posto del nome\n\n    Quest'ombrello è di Nerina; il mio invece è blu.\n    (il mio significa il mio ombrello)\n\n### Uso dell'articolo davanti ai possessivi\n| Davanti ai... | Sì / No | Esempi |\n|---|---|---|\n| pronomi possessivi | si mette sempre | Che macchina prendiamo? La mia? |\n| aggettivi possessivi con i nomi non di famiglia | si mette sempre | Il suo lavoro, la nostra amicizia, i miei capelli, le tue idee |\n| con i nomi di famiglia con un nome singolare | non si mette | mia sorella, tua cugina, suo zio, nostra madre, vostra cognata |\n| con un nome plurale | si mette | le mie sorelle, le tue cugine, i suoi zii, le nostre zie |\n| con loro | si mette sempre | il loro zio, la loro mamma, i loro nonni, le loro sorelle |\n| con un nome alterato (anche se sing.) | si mette | il mio fratellino, la sua cuginetta |\n| con un nome modificato: da un aggettivo o da una specificazione | si mette | il mio caro papà, i miei zii di Verona |\n\nNella frase\n\nLa tua camicia è celeste\n\ntua indica che tu sei il proprietario della camicia, che la camicia appartiene a te.\n\n---\n\nL'italiano per studiare\nGrammatica 17",
