     "instruction": "Completa le frasi usando gli aggettivi indefiniti elencati.",
     "body": "alcuni • troppo • altrettanta • parecchi • pochi • tutta • tutto\n\n1. Per fare un caffè bastano ___ minuti.\n2. Mio cugino lavora nell'informatica e guadagna ___ soldi.\n3. In questo periodo mi va ___ male.\n4. Non posso pulire ___ la casa in dieci minuti.\n5. Qui c'è ___ rumore, andiamo via.\n6. Abbiamo molta fame e voi ne avete ___.",
     "answerBody": "1. qualche quaderno – alcuni quaderni\n2. … **qualche** giorno – **alcuni giorni**\n3. … **qualche** ragazza – **alcune ragazze**\n4. … **qualche** pagina – **alcune pagine**\n5. … **qualche** cane – **alcuni cani**",
