     "instruction": "Completa le frasi coniugando al presente i verbi indicati tra parentesi.",
     "body": "1. Mia mamma ___ (avere) due sorelle.\n2. Gli studenti ___ (essere) tutti in classe.\n3. Tibor ___ (parlare) volentieri con tutti.\n4. Io ___ (finire) di studiare dopo cena.\n5. Voi due ___ (andare) nella stessa scuola?\n6. Noi ___ (leggere) questo libro in classe.\n7. Alberto ___ (scrivere) in modo poco chiaro.\n8. Forse Marta non ___ (sapere) il mio indirizzo.\n9. Mio cugino ___ (cercare) lavoro, ma non lo ___ (trovare).\n10. Gli zii ___ (venire) a trovarci tutte le domeniche.",
     "answerBody": "1. Mia mamma ha (avere) due sorelle.\n2. Gli studenti sono (essere) tutti in classe.\n3. Tibor parla (parlare) volentieri con tutti.\n4. Io finisco (finire) di studiare dopo cena.\n5. Voi due andate (andare) nella stessa scuola?\n6. Noi leggiamo (leggere) questo libro in classe.\n7. Alberto scrive (scrivere) in modo poco chiaro.\n8. Forse Marta non sa (sapere) il mio indirizzo.\n9. Mio cugino cerca (cercare) lavoro, ma non lo trova (trovare).\n10. Gli zii vengono (venire) a trovarci tutte le domeniche.",
