   "title": "Il passato prossimo",
   "file": "scheda25_ilpassatoprossimo.md",
   "theory": "## Il passato prossimo\nIL PASSATO PROSSIMO È UN TEMPO COMPOSTO DEL MODO INDICATIVO.\n\nIl passato prossimo indica un'azione passata.\nLe azioni al passato prossimo sono avvenute in un passato vicino:\n\n> Stamattina ho mangiato pane e marmellata.\n\noppure in un passato lontano, ma i cui effetti durano ancora nel presente:\n\n> Sono nato nel 1989.\n\nIl passato prossimo è un tempo composto, cioè è fatto di due parole:\n\n| HO GIOCATO | | SONO ANDATO | |\n|---|---|---|---|\n| ausiliare | participio passato | ausiliare | participio passato |\n\nL'ausiliare del passato prossimo può essere il tempo presente di avere, oppure di essere (vedremo dopo quando si usa l'uno o l'altro).\n\nIl participio passato è una forma verbale che si ottiene sostituendo la desinenza -are, -ere, -ire dell'infinito con la desinenza -ato, -uto, -ito.\n\n- parlare → parlato\n- credere → creduto\n- sentire → sentito\n\nEsistono molti participi passati irregolari. Ecco un elenco di quelli più importanti.\n\n| Infinito | Participio passato | Infinito | Participio passato | Infinito | Participio passato | Infinito | Participio passato |\n|---|---|---|---|---|---|---|---|\n| fare | fatto | accendere | acceso | leggere | letto | spendere | speso |\n| bere | bevuto | mettere | messo | togliere | tolto | | |\n| chiedere | chiesto | nascere | nato | vincere | vinto | | |\n| chiudere | chiuso | nascondere | nascosto | rompere | rotto | | |\n| decidere | deciso | prendere | preso | scegliere | scelto | | |\n| dipingere | dipinto | rimanere | rimasto | scendere | sceso | | |\n| dividere | diviso | rispondere | risposto | scrivere | scritto | | |\n| aprire | aperto | dire | detto | morire | morto | venire | venuto |\n\nLa maggioranza dei verbi vuole l'ausiliare avere. C'è però un gruppo di verbi (detti intransitivi) che vogliono l'ausiliare essere. Sono in genere verbi che indicano un movimento (andare, arrivare, partire, tornare, venire) o un cambiamento (diventare, morire, nascere, crescere). Dato però che le eccezioni sono numerose, è necessario imparare con l'uso e a memoria qual è l'ausiliare giusto e – in caso di dubbio – consultare il dizionario.\n\nMangiare / Andare (verbo che indica movimento):\n\n- io ho mangiato\n- io sono andato (andata)\n\n### Attenzione\nCon l'ausiliare avere il participio passato non cambia. Con l'ausiliare essere cambia, cioè concorda in genere e numero con il soggetto.\n\n- Pierpaolo è andato. Pierpaolo e Giorgio sono andati.\n- Mariella è andata. Mariella e Carla sono andate.\n\nAnche con l'ausiliare avere il participio passato cambia come genere e numero, quando il passato prossimo è preceduto dal pronome personale lo, la, li, le.\n\nVedi Scheda 11, I pronomi.\n\n- Hai mangiato il pane? – Sì, l'ho mangiato.\n- Hai mangiato la pizza? – Sì, l'ho mangiata.\n- Hai mangiato i pomodori? – Sì, li ho mangiati.\n- Hai mangiato le patate? – Sì, le ho mangiate.\n\n---\n\n## Esercizi – Grammatica 25",
