   "id": 26,
   "title": "La differenza tra imperfetto e passato prossimo",
   "file": "scheda26_differenzaimperfettoepassatoprossimo.md",
   "theory": "## La differenza tra imperfetto e passato prossimo\nL'IMPERFETTO E IL PASSATO PROSSIMO SONO DUE TEMPI DEL PASSATO MOLTO USATI IN ITALIANO.\n\nNelle Schede 24 e 25 abbiamo già visto quando si usano, ma è molto importante metterli a confronto per capirne bene le differenze di significato.\n\n### L'USO\n| Imperfetto | Passato prossimo |\n|---|---|\n| azione abituale, che si faceva sempre | azione non abituale, che è stata fatta una sola volta |\n| Da bambino andavo al mare tutte le domeniche. | Da bambino una volta sono andato al mare. |\n| azione ripetitiva, che si faceva tante volte | azione puntuale, avvenuta una volta |\n| Mia zia faceva sempre dei dolci buonissimi. | Mia zia ieri ha fatto dei dolci buonissimi. |\n| azione durativa, che è durata per un certo tempo | azione momentanea, breve, che è durata o è avvenuta in un momento |\n| Ieri pioveva. | Ieri è piovuto un po'. |\n\nQuando nella stessa frase ci sono due azioni passate che sono avvenute contemporaneamente, possiamo avere tre casi:\n\n- due azioni ugualmente lunghe (durative):\n  - imperfetto + imperfetto\n  - Mentre studiavo, mia sorella preparava la cena.\n- due azioni ugualmente puntuali o momentanee:\n  - passato prossimo + passato prossimo\n  - Quando Fulvio è arrivato, lo abbiamo salutato.\n- un'azione durativa durante la quale avviene un'azione momentanea:\n  - imperfetto + passato prossimo\n  - Mentre mangiavo, è suonato il telefono.\n\n---\n\n## Esercizi – Grammatica 26",
