     "num": "01",
     "instruction": "Imperfetto o passato prossimo? Cerchia l'alternativa corretta.",
     "body": "1. Una volta qui c'era / c'è stata una pizzeria.\n2. Facevi / Hai fatto i compiti per domani?\n3. Sabato andavo / sono andato al cinema.\n4. Finalmente arrivava / è arrivato l'ultimo giorno di scuola.\n5. In Perù abitavo / ho abitato in molte città.\n6. In passato gli Italiani fumavano / hanno fumato di più.\n7. L'anno scorso andavo / sono andato in piscina tutti i giorni.\n8. Giovedì andavo / sono andato in piscina con Bruno.\n9. Da piccolo avevo / ho avuto paura dei tuoni.\n10. Da piccolo avevo / ho avuto il morbillo.",
