     "instruction": "Riscrivi il seguente testo trasformando i verbi dal presente al passato prossimo.",
     "body": "Lucia si sveglia alle sette meno un quarto, si alza dopo pochi minuti e va in bagno. Si toglie il pigiama, si lava, si asciuga, si veste, si spazzola i capelli. Poi va in cucina e fa colazione. Prima di uscire si lava i denti, si pettina, si dà un po' di profumo. Poi si infila le scarpe, si mette la giacca ed esce.\n\n___\n___\n___",
