     "instruction": "Nella seguente lettera sottolinea in blu i verbi all'indicativo e in rosso i verbi al congiuntivo.",
     "body": "> Cara Maria,\n>\n> non ho più ricevuto tue notizie. Come stai? Come stanno gli zii? Spero che vada tutto bene e che siate contenti della casa nuova. Immagino che traslocare sia stato molto faticoso. Mi ricordo che quando abbiamo cambiato casa noi otto anni fa era stato terribile. Appena ti è possibile, vorrei che tu ti ricordassi di parlare a Franco, come ti avevo chiesto, per sapere se è sempre d'accordo di venderci la macchina quando gli arriverà quella nuova. Se gli arrivasse entro la fine del prossimo mese, potremmo venire ad Asti e fare l'atto di vendita. Se invece avesse cambiato idea, dimmelo, e ci regoleremo diversamente.\n>\n> Tanti saluti agli zii e a te un forte abbraccio.\n>\n> Chiara.",
     "answerBody": "Cara Maria,\nnon **ho** più **ricevuto** (blu) tue notizie. Come **stai** (blu)? Come **stanno** (blu) gli zii? Spero che **vada** (rosso) tutto bene e che **siate** (rosso) contenti della casa nuova. Immagino che traslocare **sia stato** (rosso) molto faticoso. Mi ricordo che quando **abbiamo cambiato** (blu) casa noi otto anni fa **era stato** (blu) terribile. Appena ti **è** (blu) possibile, vorrei che tu ti **ricordassi** (rosso) di parlare a Franco, come ti **avevo chiesto** (blu), per sapere se **è** (blu) sempre d'accordo di venderci la macchina quando gli **arriverà** (blu) quella nuova. Se gli **arrivasse** (rosso) entro la fine del prossimo mese, potremmo venire ad Asti e fare l'atto di vendita. Se invece **avesse cambiato** (rosso) idea, dimmelo, e ci **regoleremo** (blu) diversamente.\nTanti saluti agli zii e a te un forte abbraccio. Chiara.",
