     "body": "1. Ho saputo che la sposa si veste di bianco. – Immagino che ___\n2. Ho sentito che gli zii hanno l'influenza. – Ho paura che ___\n3. Sono certo che siete felici. – Desidero che ___\n4. Ho visto che tutti si sono dimenticati di telefonarmi. – Mi dispiace che ___\n5. So che la signora Fiamma ha divorziato. – Suppongo che ___\n6. Mi hanno detto che Ugo ha cambiato lavoro. – È probabile che ___\n7. Sapevo che Rosi abitava qui. – Credevo che ___",
