     "body": "1. Appena puoi, passa da me. — agente / causa / luogo\n2. Ho visto un documentario sui leoni. — mezzo / argomento / luogo\n3. Andiamo a piedi. — termine / modo / mezzo\n4. Fai le cose con troppa fretta. — compagnia / causa / modo\n5. L'aereo non è partito per la nebbia. — fine / causa / termine\n6. Esco ora dall'ospedale. — agente / luogo / mezzo\n7. Con me puoi stare tranquillo. — agente / causa / compagnia\n8. La torta è stata portata da Jimmy. — agente / causa / luogo",
