     "body": "1. Ho letto e riletto questa lezione, ___ non ho capito niente.\n2. Vuoi la maglia rossa ___ quella grigia?\n3. Davide è bravissimo ___ in inglese, ___ in matematica.\n4. Signora, preferisce questo formaggio fresco ___ questo più stagionato?\n5. Questo dolce è molto grasso ___ piuttosto difficile da digerire.\n6. Nel dopoguerra, ___ dal 1945 al 1950, l'Italia era in gravi difficoltà economiche.\n7. ___ ti decidi a comportarti bene ___ non verrai più con noi.\n8. ___ tu vada, ___ tu non vada, telefonagli.",
