   "id": 40,
   "title": "Il periodo ipotetico",
   "file": "scheda40_periodoipotetico.md",
   "theory": "## Grammatica 40",
   "exercises": [
    {
     "num": "01",
     "instruction": "Forma delle frasi ipotetiche nel presente usando le seguenti coppie di espressioni. Considera le ipotesi come reali.",
     "body": "1. studiare / prendere un bel voto\n   ___\n2. mangiare troppo / fare indigestione\n   ___\n3. nevicare / giocare a palle di neve\n   ___\n4. fare bel tempo / andare a passeggio\n   ___\n5. perdere tempo / non finire il lavoro\n   ___",
     "answerBody": "- 1. studiare / prendere un bel voto → **Se studi, prendi un bel voto.**\n- 2. mangiare troppo / fare indigestione → **Se mangi troppo, fai indigestione.**\n- 3. nevicare / giocare a palle di neve → **Se nevica, giochiamo a palle di neve.**\n- 4. fare bel tempo / andare a passeggio → **Se fa bel tempo, andiamo a passeggio.**\n- 5. perdere tempo / non finire il lavoro → **Se perdo tempo, non finisco il lavoro.**",
     "matching": null,
     "passage": null,
     "categorization": null,
     "wordBank": null,
     "blanks": null
    },
    {
     "num": "02",
     "instruction": "Forma delle frasi ipotetiche nel presente usando le seguenti coppie di espressioni. Considera le ipotesi come possibili.",
     "body": "1. avere tanti soldi / fare il giro del mondo\n   ___\n2. essere un calciatore / guadagnare molto\n   ___\n3. abitare in Francia / imparare il francese\n   ___\n4. ammalarsi / chiamare il medico\n   ___\n5. potere / invitare tutti al ristorante\n   ___",
     "answerBody": "- 1. avere tanti soldi / fare il giro del mondo → **Se avessi tanti soldi, farei il giro del mondo.**\n- 2. essere un calciatore / guadagnare molto → **Se fossi un calciatore, guadagnerei molto.**\n- 3. abitare in Francia / imparare il francese → **Se abitassi in Francia, imparerei il francese.**\n- 4. ammalarsi / chiamare il medico → **Se mi ammalassi, chiamerei il medico.**\n- 5. potere / invitare tutti al ristorante → **Se potessi, inviterei tutti al ristorante.**",
     "matching": null,
     "passage": null,
     "categorization": null,
     "wordBank": null,
     "blanks": null
    },
    {
     "num": "03",
     "instruction": "Forma delle frasi ipotetiche nel passato usando le seguenti coppie di espressioni. Considera le ipotesi come impossibili.",
     "body": "1. andare a casa degli zii / vedere Adriana\n   ___\n2. esserci il sole / abbronzarsi\n   ___\n3. essere promosso / essere più contento\n   ___\n4. aver mangiato di meno / digerire\n   ___\n5. non comportarsi male / non essere punito dall'insegnante\n   ___",
     "answerBody": "- 1. andare a casa degli zii / vedere Adriana → **Se fossi andato a casa degli zii, avresti visto Adriana.**\n- 2. esserci il sole / abbronzarsi → **Se ci fosse stato il sole, ci saremmo abbronzati.**\n- 3. essere promosso / essere più contento → **Se fosse stato promosso, sarebbe stato più contento.**\n- 4. aver mangiato di meno / digerire → **Se avessi mangiato di meno, avresti digerito.**\n- 5. non comportarsi male / non essere punito dall'insegnante → **Se non ti fossi comportato male, non saresti stato punito dall'insegnante.**",
     "matching": null,
     "passage": null,
     "categorization": null,
     "wordBank": null,
     "blanks": null
    },
    {
     "num": "04",
     "instruction": "Riscrivi correttamente le frasi.",
     "body": "1. Se studierei di più, prenderei dei bei voti.\n   ___\n2. Se studiavo, stavo promosso.\n   ___\n3. Se mi telefonavi, venivo a prenderti.\n   ___\n4. Se avrò i soldi, mi comprerei gli occhiali da sole come Elsi.\n   ___\n5. Se papà lo lasciasse, andasse a casa.\n   ___",
     "answerBody": "- 1. Se studierei di più, prenderei dei bei voti. → **Se studiassi di più, prenderei dei bei voti.**\n- 2. Se studiavo, stavo promosso. → **Se avessi studiato, sarei stato promosso.**\n- 3. Se mi telefonavi, venivo a prenderti. → **Se mi avessi telefonato, sarei venuto a prenderti.**\n- 4. Se avrò i soldi, mi comprerei gli occhiali da sole come Elsi. → **Se avessi i soldi, mi comprerei gli occhiali da sole …**\n- 5. Se papà lo lasciasse, andasse a casa. → **Se papà lo lasciasse, andrebbe a casa.**",
     "matching": null,
     "passage": null,
     "categorization": null,
     "wordBank": null,
     "blanks": null
    },
    {
     "num": "05",
     "instruction": "Unisci con una freccia ogni frase della prima colonna con una frase della seconda colonna, in base al senso.",
     "body": "1. Se riesco a finire in tempo questo lavoro,\n2. Se i miei trovassero un appartamento più grande,\n3. Se suo padre non fosse morto,\n4. Se nascessi un'altra volta,\n5. Se domani mi interroga di geografia,\n6. Se Giovanna ci invitasse a cena,\n\na. Rita non avrebbe avuto un'infanzia così triste.\nb. vorrei essere un pescatore dei mari del Sud.\nc. non so niente.\nd. potremmo portarle una bottiglia di spumante.\ne. mi rilasso e guardo un po' la televisione con voi.\nf. la zia potrebbe venire a stare con noi.",
     "answerBody": "- 1. Se riesco a finire in tempo questo lavoro, → **e. mi rilasso e guardo un po' la televisione con voi.**\n- 2. Se i miei trovassero un appartamento più grande, → **f. la zia potrebbe venire a stare con noi.**\n- 3. Se suo padre non fosse morto, → **a. Rita non avrebbe avuto un'infanzia così triste.**\n- 4. Se nascessi un'altra volta, → **b. vorrei essere un pescatore dei mari del Sud.**\n- 5. Se domani mi interroga di geografia, → **c. non so niente.**\n- 6. Se Giovanna ci invitasse a cena, → **d. potremmo portarle una bottiglia di spumante.**",
     "matching": null,
     "passage": null,
     "categorization": null,
     "wordBank": null,
     "blanks": null
    }
   ]
