     "body": "1. In Italia non (potere) ___ fumare al ristorante, anche se (fumare) ___ la sigaretta elettronica.\n2. Il numero dei matrimoni è calato: i giovani non (sposarsi) ___ più come una volta e (preferire) ___ convivere.\n3. Quando (divertirsi) ___ il tempo (volare) ___.\n4. Cosa (dire) ___ a una persona che compie gli anni?\n5. Quando arrivi in cima alla montagna (rimanere) ___ senza fiato: il panorama è stupendo.\n6. Durante le vacanze (rilassarsi) ___ e (incontrare) ___ persone nuove.",
