     "body": "1. Chi porta le fotocopie al preside? – ___ ___ porto io mentre vado in segreteria.\n2. Chi restituisce i soldi agli zii? – ___ ___ restituiremo noi domenica.\n3. Chi scrive un biglietto di auguri a Marta? – ___ ___ scrivo io volentieri.\n4. Chi prepara la merenda ai bambini? – ___ ___ prepara mia mamma.\n5. Mi impresti il libro di geografia? – Oggi mi serve; ___ ___ impresterò domani.\n6. Ho sete, berrei una bibita. – Andiamo al bar, ___ ___ offro io.\n7. Quando mi regali un videogioco nuovo? – ___ ___ regalerò per il tuo compleanno.",
     "answerBody": "1. Chi porta le fotocopie al preside? – *Gliele* porto io mentre vado in segreteria.\n2. Chi restituisce i soldi agli zii? – *Glieli* restituiremo noi domenica.\n3. Chi scrive un biglietto di auguri a Marta? – *Glielo* scrivo io volentieri.\n4. Chi prepara la merenda ai bambini? – *Gliela* prepara mia mamma.\n5. Mi impresti il libro di geografia? – Oggi mi serve; *te lo* impresterò domani.\n6. Ho sete, berrei una bibita. – Andiamo al bar, *te la* offro io.\n7. Quando mi regali un videogioco nuovo? – *Te lo* regalerò per il tuo compleanno.",
