     "heading": "Scegli tra participio e gerundio.",
     "body": "Montalbano è il commissario (nascere) ___ dalla penna di Andrea Camilleri. Le sue indagini, (ambientare) ___ nella cittadina siciliana immaginaria di Vigata, sono diventate una delle serie TV più seguite, (rimanere) ___ fedeli il più possibile alle trame dei gialli (scrivere) ___ dall’autore siciliano. Gli ascolti in TV sono da record e rispecchiano anche i giudizi positivi della critica televisiva, (rendere) ___ “Il Commissario Montalbano” una delle serie di film per la tv più (vedere) ___ di tutti i tempi. Benché si tratti di una serie televisiva, ogni episodio è girato come un film TV a sé stante (legare) ___ agli altri da una labile trama orizzontale.",
