     "heading": "Completa le frasi con il pronome riflessivo di forma debole:",
     "body": "1. – Come ___ chiamate?\n– Io ___ chiamo Carlo e la mia amica ___ chiama Anna.\n2. – Questi posti sono liberi? ___ possiamo sedere qui?\n– Sì, prego.\n3. – Marco, ___ ricordi di invitare Fabio a cena?\n– Sì, lo chiamo tra cinque minuti.\n4. – Non è che ___ stai annoiando?\n– No, sono solo stanco.\n5. – Francesco ___ laurea domani.\n– Davvero?\n6. – Quanto tempo ___ fermate qui?\n– Solo per qualche giorno.\n7. – Alessia non ___ fida mai di nessuno.\n– E tu ... ___ fidi di tutti?\n8. – Mamma, possiamo fare il bagno?\n– Sì, ma non ___ allontanate troppo!\n9. – I nonni ___ stanno riposando ... non fate rumore!\n10. – Tutto questo traffico non ___ stressa?\n– No, per niente! Mi piace guidare!\n11. – Stefano non ___ smuove dalla poltrona ... noi che facciamo? Usciamo lo stesso?\n12. – Anche se ___ sto sgolando ... nessuna mi ascolta!\n13. – Non ___ scoraggiate ... i risultati arriveranno.\n14. – Anche se ___ stiamo scervellando ... non troviamo la soluzione!\n15. – Quando vediamo questo film, ___ commuoviamo sempre.",
     "answerBody": "1. – Come **vi** chiamate?\n– Io **mi** chiamo Carlo e la mia amica **si** chiama Anna.\n2. – Questi posti sono liberi? **Ci** possiamo sedere qui?\n– Sì, prego.\n3. – Marco, **ti** ricordi di invitare Fabio a cena?\n– Sì, lo chiamo tra cinque minuti.\n4. – Non è che **ti** stai annoiando?\n– No, sono solo stanco.\n5. – Francesco **si** laurea domani.\n– Davvero?\n6. – Quanto tempo **vi** fermate qui?\n– Solo per qualche giorno.\n7. – Alessia non **si** fida mai di nessuno.\n– E tu ... **ti** fidi di tutti?\n8. – Mamma, possiamo fare il bagno?\n– Sì, ma non **vi** allontanate troppo!\n9. – I nonni **si** stanno riposando ... non fate rumore!\n10. – Tutto questo traffico non **ti** stressa?\n– No, per niente! Mi piace guidare!\n11. – Stefano non **si** smuove dalla poltrona ... noi che facciamo? Usciamo lo stesso?\n12. – Anche se **mi** sto sgolando ... nessuna mi ascolta!\n13. – Non **vi** scoraggiate ... i risultati arriveranno.\n14. – Anche se **ci** stiamo scervellando ... non troviamo la soluzione!\n15. – Quando vediamo questo film, **ci** commuoviamo sempre.",
