     "heading": "Scegli il passato prossimo o l'imperfetto – La musica in Italia nel Medioevo e nel Rinascimento",
     "body": "Il tipo di musica prodotta nel Medioevo era principalmente di carattere religioso come le laudi e i canti gregoriani. I canti gregoriani sono stati / erano canti religiosi per voci sole, senza strumenti di accompagnamento e prendevano / hanno preso il nome da San Gregorio Magno, che è stato / era papa dal 590 al 604.\n\nNel Rinascimento invece la musica ha cominciato / cominciava ad essere ascoltata e prodotta nelle corti. In quel periodo la musica strumentale aveva / ha avuto un grande sviluppo, i nobili che frequentavano / hanno frequentato le corti hanno amato / amavano suonare l'organo, il clavicembalo e il liuto e proprio in quegli anni nasceva / è nato il madrigale, che è stato / era un componimento poetico musicale a due o più voci, accompagnate da uno strumento. Uno dei più famosi compositori di madrigali è stato / era Giovanni Pierluigi da Palestrina, che di solito cantava / ha cantato nella cappella Sistina a Roma e componeva / ha composto più di 100 messe e 91 madrigali.",
